import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class AttackDeckWindowTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final String REVEAL="{\"type\":\"reveal_deck_window\",\"target\":\"DECK\",\"amount\":7,\"position\":\"BOTTOM\",\"attack_id\":\"bug-out\",\"bind\":\"bugs\"}";
    static final String DAMAGE="{\"type\":\"damage_per_bound\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":50,\"bind\":\"bugs\"}";
    static final String RESOLVE="{\"type\":\"resolve_deck_window\",\"target\":\"DECK\",\"ref\":\"bugs\",\"shuffle_category\":\"POKEMON\"}";
    static void check(boolean b,String s){GeneratedRuleBatch8Test.check(b,s);}
    static void atomic(ServerMatch m,Runnable r){GeneratedRuleBatch44Test.assertRejectedAtomic(m,r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static AttackDefinition attack(){return attack(REVEAL,DAMAGE,RESOLVE);}
    static AttackDefinition attack(String before,String during,String after){return BundledCombatData.attack(JsonParser.parseString("{\"id\":\"bug-out\",\"nameZh\":\"逃窜\",\"energyCost\":{},\"baseDamage\":0,\"damageType\":\"FIRE\",\"effectSupport\":\"SUPPORTED\",\"triggers\":[{\"trigger\":\"BEFORE_ATTACK\",\"effects\":["+before+"]},{\"trigger\":\"ON_ATTACK\",\"effects\":["+during+"]},{\"trigger\":\"AFTER_ATTACK\",\"effects\":["+after+"]}]}").getAsJsonObject(),EffectRegistry.standard());}
    static ServerMatch game(int firstSeed){return game(firstSeed,null,null);}
    static ServerMatch game(int firstSeed,CardDefinition actual,PokemonProfile actualProfile){String bugId=actual==null?"bug":actual.id();var defs=new ArrayList<CardDefinition>();for(String id:List.of(bugId,"plain","item","energy")){boolean p=Set.of(bugId,"plain").contains(id);defs.add(actual!=null&&id.equals(bugId)?actual:new CardDefinition(id,id,p?CardCategory.POKEMON:id.equals("item")?CardCategory.TRAINER:CardCategory.ENERGY,id.equals("item")?TrainerCategory.ITEM:TrainerCategory.NONE,"J",Set.of("international"),p,id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));}
        var bug=actualProfile==null?new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(attack(),CopyAttackTest.copier()),List.of(),EnergyType.FIRE):actualProfile;var plain=new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(new AttackDefinition("plain","Bug Out",Map.of(),0,EnergyType.COLORLESS,EffectSupport.SUPPORTED,null)));var item=BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"ITEM\",\"effects\":[{\"type\":\"draw\",\"amount\":1}]}").getAsJsonObject(),EffectRegistry.standard());var catalog=new CombatCatalog(Map.of(bugId,bug,"plain",plain),Map.of("energy",actual==null?EnergyType.COLORLESS:EnergyType.FIRE),Map.of("item",item));var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,i<16?bugId:i<32?"plain":i<44?"item":"energy"));decks.add(cards);}
        for(int seed=firstSeed;seed<firstSeed+1000;seed++){var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals(bugId)).count()<2))continue;for(UUID p:List.of(A,B)){m.chooseOpeningActive(p,GeneratedRuleBatch13Test.hand(m,p,bugId).instanceId());m.placeOpeningBench(p,GeneratedRuleBatch13Test.hand(m,p,bugId).instanceId());m.startAfterOpening(p);}OpeningTestSupport.complete(m,A,B,0);m.endTurn(A);m.endTurn(B);return m;}throw new AssertionError("No window fixture");}
    static List<CardInstance> bottom(ServerMatch m){var deck=m.privateView(A).deck();return List.copyOf(deck.subList(0,Math.min(deck.size(),7)));}
    static void settle(ServerMatch m,List<CardInstance> before,List<CardInstance> discard,List<CardInstance> window){var reveal=m.effectCardReveal();if(!window.isEmpty())m.acknowledgeEffectReveal(B,reveal.id());int count=(int)window.stream().filter(c->c.definitionId().equals("bug")).count();check(m.lastAttack().finalDamage()==count*50,"Matched wrong card/attack identity or wrong window");var expected=new HashSet<>(before);var dropped=window.stream().filter(c->m.cardDefinition(c.definitionId()).category()!=CardCategory.POKEMON).toList();expected.removeAll(dropped);check(new HashSet<>(m.privateView(A).deck()).equals(expected)&&m.privateView(A).deck().size()==expected.size()&&m.privateView(A).discard().size()==discard.size()+dropped.size()&&m.privateView(A).discard().containsAll(dropped),"Nonmatching Pokemon not returned or nonPokemon not discarded");check(m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(B),"Window left unresolved continuation");}
    public static void main(String[] args){sizes();privacyAuthority();stale();repeated();copied();homogeneousWindows();damageAndCleanup();schema();System.out.println("AttackDeckWindowTest passed: bottom physical window,0..7 short deck, printed attack count, all Pokemon returned, public faces with hidden UUID safety, owner/stale/replay, copy actor, repeated windows, conditional shuffle and damage-before-cleanup through weakness/resistance/protection");}
    static void homogeneousWindows(){for(String id:List.of("bug","plain","item")){var m=game(0);var cards=deck(m);var selected=cards.stream().filter(c->c.definitionId().equals(id)).limit(7).toList();check(selected.size()==7,"Insufficient homogeneous fixture");cards.removeAll(selected);cards.addAll(0,selected);var before=m.privateView(A).deck();var discard=m.privateView(A).discard();var random=m.randomTranscript();m.attack(A,"bug-out");settle(m,before,discard,selected);check((m.randomTranscript().size()>random.size())!=id.equals("item"),"Shuffle did not follow actual Pokemon return");}}
    static void damageAndCleanup(){for(String mode:List.of("NORMAL","WEAK","RESIST","PREVENT")){var modified=attack(REVEAL,DAMAGE,RESOLVE+",{\"type\":\"choice\",\"options\":[{\"type\":\"draw\",\"amount\":1},{\"type\":\"draw\",\"amount\":1}]}");var profile=new PokemonProfile(1000,0,null,mode.equals("WEAK")?EnergyType.FIRE:null,mode.equals("WEAK")?2:0,mode.equals("RESIST")?EnergyType.FIRE:null,mode.equals("RESIST")?30:0,1,List.of(modified),List.of(),EnergyType.FIRE);var m=game(0,null,profile);if(mode.equals("PREVENT")){var e=EffectRegistry.standard().parse(JsonParser.parseString(EffectOriginProtectionTest.shield("ATTACK","DAMAGE_ONLY","OPPONENT_ACTIVE","LEAVES_PLAY")).getAsJsonObject());m.executeEffectProgramByRule(A,active(m,A),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e)))),EffectTrigger.ON_CARD_PLAYED);}var w=bottom(m);int expected=(int)w.stream().filter(c->c.definitionId().equals("bug")).count()*50;if(mode.equals("WEAK"))expected*=2;if(mode.equals("RESIST"))expected=Math.max(0,expected-30);if(mode.equals("PREVENT"))expected=0;var discarded=w.stream().filter(c->m.cardDefinition(c.definitionId()).category()!=CardCategory.POKEMON).toList();m.attack(A,"bug-out");m.acknowledgeEffectReveal(B,m.effectCardReveal().id());check(m.effectChoicePrompt(A)!=null&&m.activePokemonView(B).damage()==expected&&m.privateView(A).discard().containsAll(discarded),"Damage or mandatory cleanup was postponed past ordinary attack text "+mode);var choice=m.effectChoicePrompt(A);m.chooseEffectOption(A,choice.resolutionId(),choice.step(),0);check(m.currentPlayer().equals(B),"Window continuation failed "+mode);}}
    static void sizes(){boolean sawPlain=false;for(int n=0;n<=8;n++){var m=game(n*20);if(n<8)m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-n);var before=m.privateView(A).deck();var old=m.privateView(A).discard();var window=bottom(m);sawPlain|=window.stream().anyMatch(c->c.definitionId().equals("plain"));var random=m.randomTranscript();m.attack(A,"bug-out");if(n>0){check(m.privateView(A).deck().equals(before)&&m.privateView(A).discard().equals(old)&&m.activePokemonView(B).damage()==0&&m.randomTranscript().equals(random),"Reveal moved cards, damaged or shuffled before ack");check(m.effectCardReveal().cardIds().equals(window.stream().map(CardInstance::definitionId).toList()),"Reveal used top or filtered before window");}else check(m.effectCardReveal()==null,"Empty deck issued impossible reveal");settle(m,before,old,window);}check(sawPlain,"No unmatched Pokemon tested");}
    static void privacyAuthority(){var m=game(0);var before=m.privateView(A).deck();var old=m.privateView(A).discard();var window=bottom(m);m.attack(A,"bug-out");var r=m.effectCardReveal();UUID watcher=new UUID(44,55);var session=MatchSession.multiplayer(m,A,B);session.addSpectator(watcher);for(UUID p:List.of(B,watcher)){var view=session.view(p,p.equals(watcher)?null:p);String json=new Gson().toJson(view);check(view.game().effectReveal().cardIds().equals(r.cardIds()),"Public faces hidden from observer");var hidden=new ArrayList<CardInstance>(m.privateView(A).deck());hidden.addAll(m.privateView(A).hand());hidden.addAll(m.privateView(A).prizes());for(var c:hidden)check(!json.contains(c.instanceId().toString()),"Public reveal leaked hidden physical UUID");}atomic(m,()->m.acknowledgeEffectReveal(A,r.id()));atomic(m,()->m.acknowledgeEffectReveal(B,UUID.randomUUID()));atomic(m,()->m.endTurn(A));settle(m,before,old,window);atomic(m,()->m.acknowledgeEffectReveal(B,r.id()));}
    @SuppressWarnings("unchecked") static List<CardInstance> deck(ServerMatch m){try{var f=ServerMatch.class.getDeclaredField("players");f.setAccessible(true);var state=((Map<?,?>)f.get(m)).get(A);var d=state.getClass().getDeclaredField("deck");d.setAccessible(true);return (List<CardInstance>)d.get(state);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    static void stale(){var m=game(0);m.attack(A,"bug-out");var r=m.effectCardReveal();Collections.swap(deck(m),0,1);atomic(m,()->m.acknowledgeEffectReveal(B,r.id()));check(m.effectCardReveal().equals(r)&&m.activePokemonView(B).damage()==0,"Stale window advanced damage or removed reveal");Collections.swap(deck(m),0,1);m.acknowledgeEffectReveal(B,r.id());}
    static void repeated(){var m=game(0);for(int i=0;i<2;i++){var before=m.privateView(A).deck();var old=m.privateView(A).discard();var w=bottom(m);m.attack(A,"bug-out");settle(m,before,old,w);if(i==0)m.endTurn(B);}}
    static void copied(){var m=game(20);var e=m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).findFirst();if(e.isEmpty()){var c=m.privateView(A).deck().stream().filter(v->v.definitionId().equals("energy")).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(A,List.of(c.instanceId()));e=Optional.of(c);}m.attachEnergy(A,e.get().instanceId(),active(m,A));var before=m.privateView(A).deck();var old=m.privateView(A).discard();var window=bottom(m);var other=m.privateView(B).deck();var option=m.copyAttackOptions(A,"copy").stream().filter(v->v.attackId().equals("bug-out")).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",option.pokemonId(),option.entrySequence(),option.attackId(),List.of(),List.of());check(m.effectCardReveal().actor().equals(A)&&m.privateView(B).deck().equals(other),"Copy revealed provider deck");settle(m,before,old,window);}
    static void schema(){for(String invalid:List.of(REVEAL.replace("BOTTOM","TOP"),REVEAL.replace(":7",":0"),REVEAL.replace("bug-out","Bug Out"),REVEAL.replace("DECK","OPPONENT_ACTIVE"),RESOLVE.replace("POKEMON","ENERGY"))){GeneratedRuleBatch8Test.reject(()->EffectRegistry.standard().parse(JsonParser.parseString(invalid).getAsJsonObject()));}for(var parts:List.of(List.of(REVEAL,DAMAGE,""),List.of("",DAMAGE,RESOLVE),List.of(REVEAL,DAMAGE,RESOLVE+","+RESOLVE),List.of(REVEAL+",{\"type\":\"draw\",\"amount\":1}",DAMAGE,RESOLVE),List.of(REVEAL,DAMAGE,RESOLVE.replace("bugs","wrong"))))GeneratedRuleBatch8Test.reject(()->AttackProgramRules.validate(attack(parts.get(0),parts.get(1),parts.get(2))));var e=EffectRegistry.standard().parse(JsonParser.parseString(REVEAL).getAsJsonObject());GeneratedRuleBatch8Test.reject(()->TrainerProgramRules.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e))))));}
}
